class InMemoryVisitRepository extends VisitRepository {
  readonly items = new Map<string, Visit>();

  async findByAppointmentId(appointmentId: string) {
    return [...this.items.values()].find((v) => v.toSnapshot().appointmentId === appointmentId) ?? null;
  }

  async findCheckedIn() {
    return [...this.items.values()].filter((v) => v.status === 'CHECKED_IN');
  }

  async findCheckedInBetween(from: Date, to: Date) {
    return (await this.findCheckedIn()).filter((v) => {
      const at = (v.checkedInAt as Date).getTime();
      return at >= from.getTime() && at < to.getTime();
    });
  }

  async save(visit: Visit) {
    this.items.set(visit.id, visit);
  }
}

describe('VisitsService queue metrics', () => {
  const clock = new FixedClock(new Date('2026-03-02T08:00:00Z'));
  let service: VisitsService;

  beforeEach(() => {
    clock.set(new Date('2026-03-02T08:00:00Z'));
    service = new VisitsService(new InMemoryVisitRepository(), clock, new EventEmitter2());
  });

  async function visitor(appointmentId: string) {
    await service.expectVisitor({
      appointmentId,
      personId: `person-${appointmentId}`,
      practitionerId: 'dr-1',
      expectedAt: new Date('2026-03-02T10:00:00Z'),
    });
  }

  it('averages waiting times of today\'s visitors whose encounter started', async () => {
    await visitor('a');
    await visitor('b');
    await visitor('c');
    clock.set(new Date('2026-03-02T09:00:00Z'));
    await service.checkIn('a');
    await service.checkIn('b');
    await service.checkIn('c');
    await service.recordEncounterStart('a', new Date('2026-03-02T09:05:00Z'));
    await service.recordEncounterStart('b', new Date('2026-03-02T09:25:00Z'));

    expect(await service.queueMetricsToday()).toEqual({
      date: '2026-03-02',
      attended: 2,
      averageWaitingSeconds: 900,
      maxWaitingSeconds: 1500,
    });
  });

  it('excludes visitors who checked in on another day', async () => {
    await visitor('old');
    clock.set(new Date('2026-03-01T23:50:00Z'));
    await service.checkIn('old');
    await service.recordEncounterStart('old', new Date('2026-03-02T00:30:00Z'));

    clock.set(new Date('2026-03-02T08:00:00Z'));
    expect(await service.queueMetricsToday()).toMatchObject({ attended: 0, averageWaitingSeconds: null });
  });

  it('ignores encounter starts for unknown appointments', async () => {
    await expect(service.recordEncounterStart('missing', new Date())).resolves.toBeUndefined();
  });
});
